@wasm export fn energy(xs: F32Array) -> f32 {
  let mut total: f32 = 0.0;
  for x in xs {
    total += x * x;
  }
  total
}

export fn has_signal(xs: F32Array) -> bool {
  energy(xs) > 0.0
}

